CREATE DATABASE IF NOT EXISTS capstone_demo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE capstone_demo;
CREATE TABLE IF NOT EXISTS members (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS photos (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(120) NOT NULL, mime_type VARCHAR(30) NOT NULL, image_data LONGBLOB NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
